import{L as e,b as t,x as n}from"./vue-Vea_iehr.js";import{oi as r}from"./common-xd4OgJgj.js";var i=JSON.parse(`{"path":"/os/debian/c3me4wk0/","title":"允许Root远程SSH登录 | Debian","lang":"zh-CN","frontmatter":{"title":"允许Root远程SSH登录","createTime":"2026/08/25 16:51:38","permalink":"/os/debian/c3me4wk0/"},"readingTime":{"minutes":1.22,"words":366},"git":{},"filePathRelative":"os/debian/001.allow-root-remote-ssh-login.md","headers":[]}`),a={name:`001.allow-root-remote-ssh-login.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<p>在 <strong>Debian 12</strong> 系统中开启允许 SSH 远程 Root 登录的步骤如下：</p><hr><h3 id="步骤-1-修改-ssh-服务端配置" tabindex="-1"><a class="header-anchor" href="#步骤-1-修改-ssh-服务端配置"><span><strong>步骤 1：修改 SSH 服务端配置</strong></span></a></h3><ol><li><p><strong>备份原配置文件</strong>（避免操作失误）：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config.bak</span></span></code></pre></div></li><li><p><strong>编辑 SSH 配置文件</strong>：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config</span></span></code></pre></div></li><li><p><strong>找到并修改以下参数</strong>：</p><ul><li><p>将 <code>PermitRootLogin</code> 的值改为 <code>yes</code>（如果行首有 <code>#</code> 注释符，需删除注释）：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PermitRootLogin yes</span></span></code></pre></div></li><li><p>确保允许密码认证（如果禁用密码需同时修改）：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PasswordAuthentication yes</span></span></code></pre></div></li></ul></li><li><p><strong>保存并退出编辑器</strong>（Nano 快捷键：<code>Ctrl+O</code> 保存，<code>Ctrl+X</code> 退出）。</p></li></ol><hr><h3 id="步骤-2-重启-ssh-服务" tabindex="-1"><a class="header-anchor" href="#步骤-2-重启-ssh-服务"><span><strong>步骤 2：重启 SSH 服务</strong></span></a></h3><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div><hr><h3 id="步骤-3-验证配置" tabindex="-1"><a class="header-anchor" href="#步骤-3-验证配置"><span><strong>步骤 3：验证配置</strong></span></a></h3><ol><li><p><strong>检查服务状态</strong>：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div><ul><li>确保服务处于 <code>active (running)</code> 状态。</li></ul></li><li><p><strong>测试远程 Root 登录</strong>（从另一台机器执行）：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root@your_server_ip</span></span></code></pre></div><ul><li>输入 Root 密码，确认能否成功登录。</li></ul></li></ol><hr><h3 id="步骤-4-配置防火墙放行-ssh" tabindex="-1"><a class="header-anchor" href="#步骤-4-配置防火墙放行-ssh"><span><strong>步骤 4：配置防火墙放行 SSH</strong></span></a></h3><p>如果系统启用了防火墙（如 <code>ufw</code>），需放行 SSH 端口（默认 <code>22</code>）：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 22/tcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div><hr><h3 id="恢复默认配置-禁止-root-登录" tabindex="-1"><a class="header-anchor" href="#恢复默认配置-禁止-root-登录"><span><strong>恢复默认配置（禁止 Root 登录）</strong></span></a></h3><ol><li><p>将 <code>PermitRootLogin</code> 改为 <code>no</code> 或 <code>prohibit-password</code>：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PermitRootLogin prohibit-password</span></span></code></pre></div></li><li><p>重启 SSH 服务：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div></li></ol><hr><h3 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span><strong>总结</strong></span></a></h3><ul><li><strong>风险提示</strong>：直接开放 Root 远程登录会增加服务器被暴力破解的风险，建议仅在必要时临时开启。</li><li><strong>推荐替代方案</strong>：通过普通用户登录后切换至 Root（<code>su -</code> 或 <code>sudo</code>）。</li></ul>`,20)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};